static fk_formal_budget_gate_result formal_budget_gate(
        bool base_accounting_valid,
        uint64_t hard_budget_violations,
        uint64_t configured_quic_cid_reserved_bytes,
        uint64_t observed_quic_cid_reserved_bytes,
        uint64_t configured_owner_flow_bindings_reserved_bytes,
        uint64_t observed_owner_flow_bindings_reserved_bytes,
        bool identity_loss_accounting_complete,
        uint64_t identity_integrity_failures) {
    const bool cid_budgeted =
        configured_quic_cid_reserved_bytes != 0u &&
        configured_quic_cid_reserved_bytes ==
            observed_quic_cid_reserved_bytes;
    const bool owner_bindings_budgeted =
        configured_owner_flow_bindings_reserved_bytes != 0u &&
        configured_owner_flow_bindings_reserved_bytes ==
            observed_owner_flow_bindings_reserved_bytes;
    fk_formal_budget_gate_input input{};
    input.base_accounting_valid = base_accounting_valid;
    input.quic_cid_map_connected = kQuicCidMapConnected;
    input.quic_cid_map_in_controlled_ceiling = cid_budgeted;
    input.quic_cid_map_reserved_bytes =
        observed_quic_cid_reserved_bytes;
    input.hard_budget_violations = hard_budget_violations;
    input.quic_identity_parser_complete =
        kQuicIdentityParserComplete;
    input.quic_identity_semantic_ordering_connected =
        kQuicIdentitySemanticOrderingConnected;
    input.owner_flow_bindings_connected =
        kOwnerFlowBindingsConnected;
    input.owner_flow_bindings_in_controlled_ceiling =
        owner_bindings_budgeted;
    input.owner_flow_bindings_reserved_bytes =
        observed_owner_flow_bindings_reserved_bytes;
    input.identity_loss_accounting_complete =
        identity_loss_accounting_complete;
    input.identity_integrity_failures = identity_integrity_failures;
    return fk_formal_budget_gate_evaluate(&input);
}

static const char *rss_algorithm_name(enum rte_eth_hash_function algorithm) {
    switch (algorithm) {
    case RTE_ETH_HASH_FUNCTION_DEFAULT: return "driver_default";
    case RTE_ETH_HASH_FUNCTION_TOEPLITZ: return "toeplitz";
    case RTE_ETH_HASH_FUNCTION_SIMPLE_XOR: return "simple_xor";
    case RTE_ETH_HASH_FUNCTION_SYMMETRIC_TOEPLITZ:
        return "symmetric_toeplitz_xor";
    case RTE_ETH_HASH_FUNCTION_SYMMETRIC_TOEPLITZ_SORT:
        return "symmetric_toeplitz_sort";
    case RTE_ETH_HASH_FUNCTION_MAX: break;
    }
    return "unknown";
}

constexpr uint64_t milliseconds_to_nanoseconds(uint32_t milliseconds) {
    return static_cast<uint64_t>(milliseconds) * 1000000ull;
}

constexpr uint64_t microseconds_to_nanoseconds(uint32_t microseconds) {
    return static_cast<uint64_t>(microseconds) * 1000ull;
}

static_assert(milliseconds_to_nanoseconds(3000u) == 3000000000ull);
static_assert(microseconds_to_nanoseconds(1000u) == 1000000ull);
static_assert(
    milliseconds_to_nanoseconds(kFormalFlowIdleTimeoutMs) ==
    FK_ACTOR_SESSION_DEFAULT_IDLE_NS);

static bool checked_accumulate_u64(uint64_t &total, uint64_t value) {
    if (value > UINT64_MAX - total)
        return false;
    total += value;
    return true;
}

struct IdentityTerminalAccounting {
    bool loss_accounting_complete = false;
    uint64_t recorded_loss_or_reject_events = 0u;
    uint64_t integrity_failures = 0u;
};

static bool quic_fixed_owner_accounting_conserved(
        const fk_quic_cid_map *map,
        const fk_quic_cid_map_config &config,
        const fk_quic_cid_map_stats &stats) {
    if (map == nullptr || config.fixed_owner_count == 0u ||
        config.maximum_connections_per_fixed_owner == 0u ||
        stats.peak_active_connections_per_fixed_owner >
            config.maximum_connections_per_fixed_owner)
        return false;

    uint64_t active_sum = 0u;
    for (uint16_t owner = 0u;
         owner < config.fixed_owner_count; ++owner) {
        uint32_t active = 0u;
        if (!fk_quic_cid_map_get_fixed_owner_active_connections(
                map, owner, &active) ||
            active > config.maximum_connections_per_fixed_owner ||
            !checked_accumulate_u64(active_sum, active))
            return false;
    }
    return active_sum == stats.active_connections &&
        active_sum <= config.maximum_connections;
}

static IdentityTerminalAccounting identity_terminal_accounting(
        const fk_quic_cid_map_stats &cid,
        const fk_quic_cid_map_config &cid_config,
        const fk_owner_flow_bindings_stats &bindings,
        bool owner_accounting_conserved,
        bool fixed_owner_accounting_conserved) {
    IdentityTerminalAccounting result{};
    uint64_t hash_chain_outcomes = cid.hash_chain_lookup_rejects;
    uint64_t short_header_outcomes = cid.short_header_resolved;
    uint64_t fixed_zero_classified =
        cid.short_header_fixed_zero_resolved;
    bool valid =
        checked_accumulate_u64(
            hash_chain_outcomes,
            cid.hash_chain_registration_rejects) &&
        checked_accumulate_u64(
            hash_chain_outcomes,
            cid.hash_chain_internal_rejects) &&
        checked_accumulate_u64(
            short_header_outcomes,
            cid.short_header_unresolved) &&
        checked_accumulate_u64(
            short_header_outcomes,
            cid.short_header_ambiguous) &&
        checked_accumulate_u64(
            fixed_zero_classified,
            cid.short_header_fixed_zero_unnegotiated_rejects) &&
        hash_chain_outcomes == cid.hash_chain_limit_rejects &&
        short_header_outcomes == cid.short_header_attempts &&
        fixed_zero_classified <=
            cid.short_header_fixed_zero_candidates &&
        cid.short_header_fixed_zero_resolved <=
            cid.short_header_resolved &&
        cid.short_header_fixed_zero_unnegotiated_rejects <=
            cid.short_header_unresolved &&
        cid.fixed_owner_capacity_rejects <=
            cid.unresolved_observations &&
        cid.peak_hash_chain_traversed <=
            cid_config.maximum_hash_chain &&
        cid.peak_short_header_hash_probes <=
            FK_QUIC_CID_MAX_BYTES &&
        cid.peak_active_connections_per_fixed_owner <=
            cid_config.maximum_connections_per_fixed_owner &&
        bindings.entry_bytes == FK_OWNER_FLOW_BINDING_ENTRY_BYTES &&
        bindings.logical_id_abi_version ==
            FK_QUIC_LOGICAL_ID_ABI_VERSION &&
        bindings.retire_ack_required == 1u &&
        bindings.maximum_connection_slots ==
            cid_config.maximum_connections &&
        owner_accounting_conserved &&
        fixed_owner_accounting_conserved;

    result.recorded_loss_or_reject_events =
        cid.unresolved_observations;
    valid = checked_accumulate_u64(
                result.recorded_loss_or_reject_events,
                bindings.counters.missing_binding_rejects) &&
        valid;

    result.integrity_failures = cid.hard_integrity_failures;
    valid = checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.owner_thread_violations) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.invalid_requests) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.bind_conflicts) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.direction_mismatch_rejects) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.cid_generation_mismatch_rejects) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.fixed_owner_mismatch_rejects) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.slot_reuse_before_retire_ack_rejects) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.retire_expectation_mismatch_rejects) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.slot_out_of_range_rejects) &&
        checked_accumulate_u64(
                result.integrity_failures,
                bindings.counters.state_integrity_failures) &&
        valid;
    result.loss_accounting_complete = valid;
    return result;
}

static void handle_signal(int) {
    g_signal_stop = 1;
}

