enum QueueDepthStage : size_t {
    QUEUE_DEPTH_RX_HANDOFF_AGGREGATE = 0u,
    QUEUE_DEPTH_FLOW_OPEN_INPUT = 1u,
    QUEUE_DEPTH_CHECKPOINT_INPUT = 2u,
    QUEUE_DEPTH_REORDER = 3u,
    QUEUE_DEPTH_LEGACY_DETECTOR_AGGREGATE = 4u,
    QUEUE_DEPTH_EVENT_STUDENT_COMMAND = 5u,
    QUEUE_DEPTH_EVENT_STUDENT_RESULT = 6u,
    QUEUE_DEPTH_FKERES_WRITER_RING = 7u,
    QUEUE_DEPTH_STAGE_COUNT = 8u,
};

/*
 * Numerically stable, single-pass OLS state for depth = a + b*time.  The
 * monitor owns this state, so the dataplane does not perform any additional
 * synchronization or accounting work.
 */
struct QueueDepthOls {
    uint64_t samples = 0u;
    uint64_t peak_depth = 0u;
    long double mean_elapsed_seconds = 0.0L;
    long double mean_depth = 0.0L;
    long double centered_time_square_sum = 0.0L;
    long double centered_time_depth_sum = 0.0L;
};

struct QueueDepthMeasurements {
    std::array<QueueDepthOls, QUEUE_DEPTH_STAGE_COUNT> stages{};
    QueueDepthOls aggregate{};
    uint64_t first_sample_elapsed_ns = 0u;
    uint64_t last_sample_elapsed_ns = 0u;
    uint64_t offered_interval_ns = 0u;
};

